CREATE TABLE #Accounts (
    account_id INT IDENTITY PRIMARY KEY,
    email      NVARCHAR(200) NULL
);

CREATE UNIQUE INDEX ix_accounts_email ON #Accounts (email);

INSERT INTO #Accounts (email) VALUES (N'ada@example.com');

BEGIN TRY
    INSERT INTO #Accounts (email) VALUES (N'ada@example.com');   -- duplicate
END TRY
BEGIN CATCH
    SELECT ERROR_NUMBER() AS error_number, ERROR_MESSAGE() AS error_message;
END CATCH;

INSERT INTO #Accounts (email) VALUES (NULL);

BEGIN TRY
    INSERT INTO #Accounts (email) VALUES (NULL);                   -- second NULL
END TRY
BEGIN CATCH
    SELECT ERROR_NUMBER() AS error_number, ERROR_MESSAGE() AS error_message;
END CATCH;

-- Filtered unique index: many NULLs allowed, non-NULL values still unique
DROP INDEX ix_accounts_email ON #Accounts;
CREATE UNIQUE INDEX ix_accounts_email_notnull ON #Accounts (email)
    WHERE email IS NOT NULL;
